import assert from 'node:assert/strict'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..')
const read=(relative)=>fs.readFileSync(path.join(root,relative),'utf8')
const exists=(relative)=>fs.existsSync(path.join(root,relative))
const walk=(dir)=>fs.readdirSync(dir,{withFileTypes:true}).flatMap(entry=>entry.isDirectory()?walk(path.join(dir,entry.name)):[path.join(dir,entry.name)])
const sourceFiles=walk(path.join(root,'src')).filter(file=>/\.(?:ts|vue|css)$/.test(file))
const sourceText=sourceFiles.map(file=>[path.relative(root,file),fs.readFileSync(file,'utf8')])

const release=read('src/data/release.ts')
const app=release.match(/APP_RELEASE='([^']+)'/)?.[1]
const pkgRelease=release.match(/PACKAGE_RELEASE='([^']+)'/)?.[1]
const game=release.match(/GAME_UPDATES_RELEASE='([^']+)'/)?.[1]
assert.ok(app&&pkgRelease&&game,'release.ts must expose all canonical release markers')
const pkg=JSON.parse(read('package.json'))
assert.equal(pkg.version,pkgRelease,'package.json version must match PACKAGE_RELEASE')
assert.equal(pkgRelease,`${app}.0`,'package release must derive from app release')
assert.match(read('public/sw.js'),new RegExp(`brambleheart-shell-v${app.replaceAll('.','\\.')}`),'PWA cache must match app release')
assert.ok(read('CHANGELOG.md').startsWith(`# Brambleheart Beta ${app}`),'CHANGELOG current entry must match app release')
assert.match(read('README.md'),new RegExp(`Beta ${app.replaceAll('.','\\.')}`),'README current Site Update must match app release')
assert.match(read('README.md'),new RegExp(`Game Update[^\n]*v${game.replaceAll('.','\\.')}`),'README current Game Update must match game release')
assert.match(read('PATCH_NOTES.md'),new RegExp(`Beta ${app.replaceAll('.','\\.')}`),'PATCH_NOTES current Site Update must match app release')
assert.match(read('PATCH_NOTES.md'),new RegExp(`v${game.replaceAll('.','\\.')}`),'PATCH_NOTES current Game Update must match game release')
assert.match(read('public/downloads/Brambleheart-Cloud-Instructions.txt'),new RegExp(`Beta ${app.replaceAll('.','\\.')}`),'downloadable cloud instructions must match app release')
const manifest=read('public/manifest.webmanifest')
const router=read('src/router.ts')
const installSupport=read('src/state/install.ts')
const indexHtml=read('index.html')
assert.match(manifest,/"id": "\/"[\s\S]{0,80}"start_url": "\/news"/,'Installed app identity must remain stable while launching into News')
assert.match(router,/path:'\/',redirect:'\/news'/,'Root launch route must open News so existing installs using the old root start URL also land on News')
for(const asset of ['manifest.webmanifest','icon-192.png','icon-512.png','icon-maskable-512.png','apple-touch-icon.png'])assert.ok(indexHtml.includes(asset)||manifest.includes(asset),`Install asset reference missing: ${asset}`)
assert.ok(indexHtml.includes(`manifest.webmanifest?v=${app}`),'Document manifest URL must be release-versioned')
assert.ok(manifest.includes(`icon-192.png?v=${app}`)&&manifest.includes(`icon-512.png?v=${app}`),'Installed-app icons must use release-versioned URLs')
assert.match(installSupport,/window\.addEventListener\('load'[\s\S]{0,700}refreshInstallMetadata\(\)[\s\S]{0,700}registration\.update\(\)/,'Install metadata and service-worker updates must run when Brambleheart is opened')
assert.match(installSupport,/fetch\(`\$\{path\}\?v=\$\{APP_RELEASE\}`,[^)]*cache:'reload'/,'Open-app install metadata refresh must bypass stale browser cache')
assert.doesNotMatch(installSupport,/setInterval|periodicSync|sync\.register/,'Installed-app update checks must not add background polling or sync')

const changelog=read('CHANGELOG.md')
const changelogReleases=[...changelog.matchAll(/^# Brambleheart Beta ([0-9.]+)/gm)].map(match=>match[1])
assert.deepEqual(changelogReleases,['0.12','0.11','0.10'],'Site Update history must retain the condensed three-release history')
let activeCategory='';let categoryCount=0
for(const line of changelog.split(/\r?\n/)){
  if(line.startsWith('## ')){if(activeCategory)assert.ok(categoryCount<=12,`${activeCategory} exceeds the 12-log category maximum`);activeCategory=line.slice(3).trim();categoryCount=0}
  else if(line.startsWith('- ')&&activeCategory)categoryCount++
}
if(activeCategory)assert.ok(categoryCount<=12,`${activeCategory} exceeds the 12-log category maximum`)
for(const gameRuleText of ['Wounded Health range to 5–7','Sapguard [+1]','Vinegrip [+2]','Ironwood Bulwark [+3]','Driftwood Charm','Sea of Roots','7–10 XP','Tordan Steady Pace'])assert.equal(changelog.includes(gameRuleText),false,`Game-rule history must not be duplicated in Site Changelog: ${gameRuleText}`)
for(const removed of ['Rebuilds Site Update history into five categorized releases','Consolidates the historical Site Update/package/export/PWA metadata','Reworks the News social area into Discord, Share, and Creator Content actions'])assert.equal(changelog.includes(removed),false,`Retired changelog boilerplate remains: ${removed}`)
