assert.match(monsters,/const noxiousMucklingProfile:MonsterProfile=[\s\S]{0,3000}Toxic Bash[\s\S]{0,1800}Toxic Reconstitution/,'Noxious Muckling must retain its complete monster profile')
assert.match(monsters,/const emberDyrtleProfile:MonsterProfile=[\s\S]{0,4200}Crushing Bite[\s\S]{0,3000}Furnace Pulse/,'Ember Dyrtle must retain its complete monster profile')
for(const text of ['Mucklings are low, gelatinous creatures','Noxious Mucklings are toxic cousins','Ember Dyrtles are immense, furnace-hearted beasts'])assert.ok(monsters.includes(text),`Requested monster bio missing: ${text}`)
assert.match(monsters,/name:'STRIDE'[^}]{0,700}EFFECT:[^}]{0,500}SLOSH:/,'Muckling Slosh must follow Effect as its own structured field')
assert.match(monsters,/name:'STRIDE'[^}]{0,850}SEEPING SLOSH:/,'Noxious Muckling Seeping Slosh must be present as a structured field')
assert.match(monsters,/const emberDyrtleProfile[\s\S]{0,1000}name:'STRIDE'[^}]{0,850}CINDERSTEP:/,'Ember Dyrtle Cinderstep must be present as a structured field')
for(const label of ['SLOSH','SEEPING SLOSH','CINDERSTEP'])assert.ok(rulesEngine.includes(`'${label}'`),`Structured rule parser missing monster field: ${label}`)
assert.match(rulesEngine,/RULE_FIELD_ORDER=\[[^\]]*'EFFECT','SLOSH','SEEPING SLOSH','CINDERSTEP','FORMLESS'/,'Monster movement detail fields must render immediately after Effect')
for(const [profile,next] of [['mucklingProfile','noxiousMucklingProfile'],['noxiousMucklingProfile','emberDyrtleProfile']]){const body=monsters.slice(monsters.indexOf(`const ${profile}:`),monsters.indexOf(`const ${next}:`));assert.doesNotMatch(body,/\bCreature\b|\byour\b|\bYour\b/,`${profile} must use the monster name instead of generic/player-facing references`)}
const emberProfileBody=monsters.slice(monsters.indexOf('const emberDyrtleProfile:'),monsters.indexOf('export const externalMonsters'))
assert.doesNotMatch(emberProfileBody,/\bCreature\b|\byour\b|\bYour\b/,'Ember Dyrtle profile must use the monster name instead of generic/player-facing references')
assert.match(monsters,/monster\('Muckling','Creatures of the Winds'[^\n]*monster\('Noxious Muckling','Creatures of the Winds','Muckling'[^\n]*monster\('Ember Dyrtle','Creatures of the Winds'/,'Requested profiled monsters must live in Creatures of the Winds')
for(const removed of ['Elemental Muckling','Prismheart Muckling','Rime Dyrtle','Storm Dyrtle','Verdant Dyrtle','Arcane Dyrtle'])assert.doesNotMatch(monsters,new RegExp(`monster\\('${removed.replace(/[.*+?^${}()|[\\]\\]/g,'\\$&')}'`),`Requested monster must be removed: ${removed}`)
assert.doesNotMatch(monsters,/'Generic Monsters'/,'Generic Monsters category must be replaced by Creatures of the Winds')
assert.match(monsters,/monsterCategories=\[[\s\S]{0,180}Companions[\s\S]{0,180}Creatures of the Winds[\s\S]{0,180}Arcane Automata/,'Creatures of the Winds must be the first Monsters category after Companions')
assert.match(monsters,/'Epic Legends and Tall-Tale Terrors'/,'Epic Legends and Tall-Tale Terrors category definition must remain available even when currently empty')
assert.equal((monsters.match(/(?:monster|placeholder)\('[^']+','Epic Legends and Tall-Tale Terrors'/g)||[]).length,0,'Removed Dyrtles must not leave Epic Legends monster entries behind')
assert.match(ruleReader,/monster-profile-section[\s\S]{0,5000}Actions[\s\S]{0,3000}Monstrous Traits/,'Monster profile pages must expose collapsible Actions and Monstrous Traits')
assert.match(ruleReader,/monster-profile-block\{[^}]*padding:0[^}]*overflow:hidden[^}]*\}/,'Monster profile category shells must use the thinner canonical block presentation')
assert.match(ruleReader,/monster-profile-block>summary\{padding:7px 10px\}/,'Monster profile category title bars must use reduced vertical padding')
assert.doesNotMatch(ruleReader,/monster-card-columns|monster-card-column|monsterColumns\(/,'Superseded Monster-specific independent-column implementation must be removed')
assert.match(ruleReader,/IndependentCardColumns :items="currentMonster\.profile\.actions"[\s\S]{0,500}<AbilityCard/,'Monster Actions must use the shared AbilityCard authority')
assert.match(ruleReader,/IndependentCardColumns :items="currentMonster\.profile\.monstrousTraits"[\s\S]{0,500}<AbilityCard/,'Monstrous Traits must use the shared AbilityCard authority')
assert.doesNotMatch(ruleReader,/monster-trait-card/,'Monstrous Traits must not override canonical Ability-family tone')
assert.match(ruleReader,/currentMonster\.bio\|\|currentMonster\.summary/,'Monster profile overview must prefer authored bio text')
assert.match(ruleReader,/monsterArtModules/,'Monster artwork must declare one reusable asset authority')
assert.match(ruleReader,/currentMonsterArt/,'Monster profiles must resolve artwork through the shared monster-art authority')
assert.match(ruleReader,/monster-profile-art-placeholder/,'Monster profiles must render a fallback artwork placeholder when no asset exists')
assert.match(ruleReader,/group\.category\.name==='Creatures of the Winds'[\s\S]{0,900}deadlier and stranger creatures/,'Monster index must introduce the deadlier categories after Creatures of the Winds')
assert.doesNotMatch(ruleReader,/monster-profile-section[\s\S]{0,9000}<h3>Keywords<\/h3>/,'Monster profiles must not retain a redundant Keywords section')
assert.match(ruleReader,/monsterThreatLabel[\s\S]{0,500}profile\?`TL \${monster\.profile\.threatLevel}`:'TL —'/,'Monster index Threat Level detail must derive from the Monster profile authority')
assert.match(ruleReader,/monster-family-link[\s\S]{0,300}monsterThreatLabel\(family\.parent\)/,'Monster index links must display Threat Level detail beside the name')
assert.match(ruleReader,/RuleCollapsibleCard[\s\S]{0,300}monster-category-section/,'Monster categories must use the shared expandable rule-card authority')
const requiredMonsterCategories=['Companions','Arcane Automata','Eldritch Abominations','Insectoid Terrors','Creatures of the Winds','Necrotic Horrors','Primordial Entities','Verdant Aberrations']
for(const category of requiredMonsterCategories){const escaped=category.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const count=(monsters.match(new RegExp(`(?:monster|placeholder)\\('(?:[^']+)'\\s*,\\s*'${escaped}'`,'g'))||[]).length;assert.ok(count>=10,`${category} must contain at least 10 monsters`)}
for(const name of ['Muckling','Noxious Muckling','Ember Dyrtle','Undeath Sorcerer','Lich Archregent','Lich Lord','Undeath Warrior','Crypt Guard','Legionnaire','Graveborn Horror','Terrorghiest','Necrotide','Ghoul Pack','Tempest Warden','Blightroot Treant','Fungal Behemoth','Leafshroud Guardian','Mossclad Stalker','Thorned Bramblefiend','Thornblade Nymphs','Verdant Lurker','Vinecrawler','Voracious Bramblebeast'])assert.match(monsters,new RegExp(`monster\\('${name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}'`),`Sourced monster must remain sourced: ${name}`)
assert.match(rulePageLayout,/parents\?:RuleBreadcrumbParent\[\][\s\S]{0,700}breadcrumbParents/,'Rules page layout must support reusable multi-level breadcrumbs')
assert.match(ruleReader,/monsterIndexParent=computed\(\(\)=>currentMonster\.value\?\.category==='Companions'[\s\S]{0,180}Critters & Companions[\s\S]{0,180}label:'Monsters'/,'Creature breadcrumbs must resolve through the correct Watcher index page')
assert.match(ruleReader,/if\(currentMonster\.value\)return\[[\s\S]{0,220}label:'The Watcher'[\s\S]{0,220}monsterIndexParent\.value/,'Creature breadcrumbs must include The Watcher and the category-appropriate creature index')
assert.match(ruleReader,/layoutBackTo=computed\(\(\)=>currentMonster\.value\?monsterIndexParent\.value\.path:'\/rules'\)/,'Creature profile Back navigation must return to the same category-appropriate index page')
for(const slug of ['encounters-threat-level','critters','traps-environments','monsters','rewards'])assert.ok(catalog.includes(`page('${slug}'`),`Watcher core navigation page missing: ${slug}`)
assert.match(catalog,/categoryNavigationPages=ruleCategories\.flatMap\(category=>\[[\s\S]{0,180}category\.pages/,'Watcher core pages must participate in the shared sequential navigation authority')
assert.doesNotMatch(catalog,/ruleNavigationPages=\[[^\n]*monsterRulePages/,'Individual monster profiles must remain outside sequential previous/next navigation')
assert.match(catalog,/lore-anthro-mundas-hallows','Hollowing Hallows'[\s\S]{0,180}'THE HOLLOWING HALLOWS'/,'Hollowing Hallows catalog title and source heading must use current terminology')
assert.match(rules,/THE HOLLOWING HALLOWS[\s\S]{0,700}Beyond the veil of the living world lies the Hollowing Hallows[\s\S]{0,3000}No spiritwalker has ever returned with a true map[\s\S]{0,3200}The Hallows may stand upon the threshold of that answer/,'Hollowing Hallows must contain the supplied replacement lore text')

assert.match(news,/discord-community-image\{height:144px\}/,'News Discord image must align with the Creator Content desktop height')
assert.match(news,/news-promo-count[^{]*\{[^}]*color:color-mix\([^)]*detail-trait-heritage/,'News community counts must use the muted green treatment')
const changelogView=read('src/views/ChangelogView.vue')
assert.match(changelogView,/ReleaseCategory/,'Site Changelog must model categorized releases')
assert.match(changelogView,/changelog-category-stack/,'Site Changelog must render release categories')
console.log(`Brambleheart integrity checks passed for Site ${app} / Game Update ${game}.`)
